import MenuIcon from "@mui/icons-material/Menu";
import Link from "@mui/material/Link";
import Typography from "@mui/material/Typography";
import Avatar from "@mui/material/Avatar";
import AppBar from "@mui/material/AppBar";
import Box from "@mui/material/Box";
import Divider from "@mui/material/Divider";
import Drawer from "@mui/material/Drawer";
import IconButton from "@mui/material/IconButton";
import List from "@mui/material/List";
import ListItem from "@mui/material/ListItem";
import ListItemButton from "@mui/material/ListItemButton";
import ListItemText from "@mui/material/ListItemText";
import Toolbar from "@mui/material/Toolbar";
import React, { Fragment } from "react";
import "../App.css";
import dp from "../Assets/Images/ashutosh.webp";

const drawerWidth = 170;
const navItems = [
  { name: "Home", id: "" },
  { name: "About", id: "#About" },
  { name: "Project", id: "#Project" },
  { name: "Qualification", id: "#Qualification" },
  { name: "Skills", id: "#Skills" },
];

const Header = (props) => {
  const { window } = props;
  const [mobileOpen, setMobileOpen] = React.useState(false);

  const handleDrawerToggle = () => {
    setMobileOpen((prevState) => !prevState);
  };

  const drawer = (
    <Box onClick={handleDrawerToggle} sx={{ textAlign: "center" }}>
      <Typography
        component={"span"}
        variant="h6"
        sx={{ fontFamily: "Cinzel Decorative", fontWeight: 700 }}
      >
        A
      </Typography>
      <Typography
        component={"span"}
        variant="h6"
        sx={{ fontFamily: "Fredericka the Great" }}
      >
        B
      </Typography>
      <Divider />
      <List>
        {navItems.map((item) => (
          <ListItem key={item.name} disablePadding>
            <ListItemButton
              component="a"
              href={item.id}
              sx={{ textAlign: "center" }}
            >
              <ListItemText primary={item.name} />
            </ListItemButton>
          </ListItem>
        ))}
      </List>
    </Box>
  );

  const container =
    window !== undefined ? () => window().document.body : undefined;

  return (
    <Fragment>
      <AppBar className="appbar" component="nav" sx={{ background: "black" }}>
        <Toolbar>
          <IconButton
            color="inherit"
            aria-label="open drawer"
            edge="start"
            onClick={handleDrawerToggle}
            sx={{ mr: 2, display: { sm: "flex", md: "none" } }}
          >
            <MenuIcon />
          </IconButton>
          <Avatar
            src={dp}
            sx={{
              display: { xs: "none", sm: "none", md: "flex" },
            }}
          />
          <Typography
            className="avtar"
            variant="h6"
            component="div"
            sx={{
              flexGrow: 1,
              display: { xs: "flex", sm: "flex" },
              fontFamily: "serif",
            }}
          >
            ASHUTOSH BAJPAI
          </Typography>
          <Box sx={{ display: { xs: "none", sm: "none", md: "flex" } }}>
            {navItems.map((item, index) => (
              <Link
                key={index}
                underline="none"
                href={item.id}
                sx={{
                  color: "aqua",
                  p: { md: 2, sm: 0.6 },
                  fontWeight: 400,
                  fontFamily: `serif`,
                  letterSpacing: 1,
                  fontSize: "1.2em",
                }}
              >
                {item.name}
              </Link>
            ))}
          </Box>
          <Avatar
            src={dp}
            sx={{ display: { xs: "flex", sm: "flex", md: "none" } }}
          />
        </Toolbar>
      </AppBar>
      <nav>
        <Drawer
          container={container}
          variant="temporary"
          open={mobileOpen}
          onClose={handleDrawerToggle}
          ModalProps={{
            keepMounted: true, // Better open performance on mobile.
          }}
          sx={{
            display: { xs: "flex", sm: "flex", md: "none" },
            "& .MuiDrawer-paper": {
              boxSizing: "border-box",
              width: drawerWidth,
              bgcolor: "#000",
              "& .MuiTypography-h6": {
                color: "gold",
                // fontFamily: "Cinzel Decorative",
                fontSize: "3rem",
              },
              "& .MuiDivider-fullWidth": {
                borderColor: "gold",
              },
              "& .MuiListItemButton-root": {
                color: "aqua",
              },
              "& .MuiTypography-body1": {
                fontFamily: "serif",
                fontSize: "1.2rem",
              },
            },
          }}
        >
          {drawer}
        </Drawer>
      </nav>
    </Fragment>
  );
};

export default Header;
